            var budgetUsed = ds.budgetUsed || 12;
            var scopeSize = ds.scopeSize || 100;
            var quality = ds.qualityIndex || 0;
            var adoption = ds.finalAdoption || ds.stakeholderBuyIn || 0;

            var scheduleAdherence = Math.max(0, Math.min(100, 100 - Math.max(0, (monthsElapsed - 24) / 24 * 100)));
            var costAdherence = Math.max(0, Math.min(100, 100 - Math.max(0, (budgetUsed - 12) / 12 * 100)));
            var scopeScore = Math.max(0, Math.min(100, 100 - Math.max(0, scopeSize - 100)));

            var execution = (scheduleAdherence + costAdherence + scopeScore + quality) / 4;
            var management = (Math.min(100, (ds.spi || 0) * 100) + Math.min(100, (ds.cpi || 0) * 100)) / 2;
            var stakeholder = (adoption + (ds.stakeholderBuyIn || 0)) / 2;
            var strategic = adoption;

            return Math.max(0, Math.min(100, Math.round(0.4 * execution + 0.3 * management + 0.2 * stakeholder + 0.1 * strategic)));
        }

        _ratingLabel(name) {
            var map = { 'Below Target': 'rating_below_target', 'Excellent': 'rating_excellent', 'Competent': 'rating_competent' };
            return window.mySimulation.t(map[name] || 'rating_below_target');
        }

        getPerformanceSummary(history) { var __lang=(window.mySimulation&&window.mySimulation.lang==="es")?"es":"en";
            if (!history || !history.length) return {};
            var ds = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState) || {};

