            var quality = ds.qualityIndex || 0;
            var adoption = ds.finalAdoption || ds.stakeholderBuyIn || 0;

            var scheduleAdherence = Math.max(0, Math.min(100, 100 - Math.max(0, (monthsElapsed - 24) / 24 * 100)));
            var costAdherence = Math.max(0, Math.min(100, 100 - Math.max(0, (budgetUsed - 12) / 12 * 100)));
            var scopeScore = Math.max(0, Math.min(100, 100 - Math.max(0, scopeSize - 100)));

            var finalScore = this._computeOverallScore(ds);

            var performance = 'Below Target';
            if (finalScore >= 85) performance = 'Excellent';
            else if (finalScore >= 70) performance = 'Competent';

            var insights = [];
            if (scopeSize > 120) insights.push((__lang==="es"?'El alcance creció ':'Scope grew by ') + Math.round(scopeSize - 100) + (__lang==="es"?'% — el scope creep erosionó la previsibilidad. Un control de cambios más estricto habría ayudado.':'% — scope creep eroded predictability. Tighter change control would have helped.'));
            if ((ds.spi || 1) < 0.9) insights.push((__lang==="es"?'SPI de ':'SPI of ') + (ds.spi || 1).toFixed(2) + (__lang==="es"?' indica que el cronograma se atrasó respecto al plan. Responder antes a los riesgos importa.':' indicates the schedule fell behind plan. Earlier risk response matters.'));
            if ((ds.cpi || 1) < 0.9) insights.push((__lang==="es"?'CPI de ':'CPI of ') + (ds.cpi || 1).toFixed(2) + (__lang==="es"?' señala desafíos de disciplina presupuestaria.':' signals budget discipline challenges.'));
            if (adoption < 60) insights.push((__lang==="es"?'La adopción de usuarios en ':'User adoption at ') + adoption + (__lang==="es"?'% — la resistencia no se atendió adecuadamente. La inversión en gestión del cambio rinde de forma compuesta.':'% — resistance was not adequately addressed. Change management investment returns compound.'));
            if (adoption >= 80 && finalScore >= 80) insights.push((__lang==="es"?'Entrega sólida — alcance disciplinado, gestión del cambio rigurosa, planeación realista. Refleja el 35% superior en los datos CHAOS.':'Strong delivery — disciplined scope, rigorous change management, realistic planning. This mirrors the top 35% in CHAOS data.'));
            if (ds.approach === 'waterfall' && scopeSize > 115) insights.push((__lang==="es"?'Waterfall con fuerte scope creep es el patrón clásico de fracaso empresarial — Atkinson (1999) advierte contra ello.':'Waterfall with heavy scope creep is the classic enterprise failure pattern — Atkinson (1999) warns against it.'));
            if (ds.approach === 'agile' && adoption < 60) insights.push((__lang==="es"?'Agile en una cultura manufacturera tradicional requiere más gestión del cambio y respaldo ejecutivo.':'Agile in a traditional manufacturing culture needs heavier change management and executive air cover.'));

            return {
                totalScore: finalScore,
                performance: this._ratingLabel(performance),
                scheduleAdherence: Math.round(scheduleAdherence),
                costAdherence: Math.round(costAdherence),
                scopeDiscipline: Math.round(scopeScore),
                quality: Math.round(quality),
                userAdoption: adoption,
                approach: ds.approach,
                goLive: ds.goLivePath,
                insights: insights
            };
        }

